int debounce_level(const int *levels, int n, int stable_count)
{
    if (levels == NULL || n <= 0 || stable_count <= 0) {
        return -1;
    }

    int run_value = levels[0];
    int run_len = 1;

    if (run_len >= stable_count) {
        return run_value;
    }

    for (int i = 1; i < n; i++) {
        if (levels[i] == run_value) {
            run_len++;
        } else {
            run_value = levels[i];
            run_len = 1;
        }
        if (run_len >= stable_count) {
            return run_value;
        }
    }
    return -1;
}
